from pathlib import Path
import json,copy
R=Path(__file__).resolve().parents[1]
C=json.loads((R/'course.json').read_text(encoding='utf-8'));by={l['id']:l for l in C['lessons']}
def short(q,m,ms,answer=None):
    p=dict(q=q,m=m,ms=ms,note='Indicative content: credit equivalent accurate reasoning. Do not award the same idea twice.')
    if answer is not None:p['answer']=answer
    return p
def essay(q,m,ind):
    bands=([['7–8','Accurate, developed explanation and analysis, applied closely to the context, with a supported judgement.'],['5–6','Mostly accurate knowledge and some developed application/analysis; the conclusion has support but may be uneven.'],['3–4','Some relevant knowledge and application; development or analysis is limited.'],['1–2','Isolated relevant statements with little development or application.'],['0','No creditworthy response.']] if m==8 else [['12–15','Accurate, well-selected knowledge with sustained contextual application, connected analysis and balanced evaluation leading to a well-supported judgement.'],['8–11','Generally accurate knowledge with relevant application and developed analysis/evaluation, though uneven in places; a reasoned judgement.'],['4–7','Some relevant knowledge and application; analysis/evaluation is partial or mostly asserted.'],['1–3','Basic isolated relevant statements with little application or developed reasoning.'],['0','No creditworthy response.']])
    return dict(q=q,m=m,lor=bands,ind=ind,ms=[],note='Original Prodigy best-fit levels, not AQA’s official marking grid. Assess the whole response, then choose a defensible mark within the band. Indicative content is not a point-per-mark checklist.')
def section(title,stem,checks,parts):
    mc=[]
    for id in checks:
        a=copy.deepcopy(by[id]['checks'][0]);a.update(m=1,ms=[a.pop('why')]);mc.append(a)
    result=dict(title=title,stem=stem,parts=mc+parts)
    assert sum(p['m']for p in result['parts'])==35
    return result
papers=[]
papers.append(dict(id='pe-paper-1',paper=1,title='Paper 1 · Participation and performance foundations',marks=105,minutes=120,coverage=['Applied anatomy and physiology','Skill acquisition','Sport and society'],questions=[
section('Section A · Applied anatomy and physiology','<p><b>Fictional case:</b> A rower completes a steady exercise test. At one stage heart rate is 150 beats min⁻¹, stroke volume 140 mL beat⁻¹, breathing frequency 32 min⁻¹ and tidal volume 2.5 L. Later the rower completes a maximal finishing effort.</p>',['oxygen-transport','muscle-fibres','motor-units'],[
short('Calculate minute ventilation, giving the correct unit.',2,['32 × 2.5.','80 L min⁻¹.'],80),
short('Calculate cardiac output in L min⁻¹, showing your working.',3,['150 × 140 = 21 000 mL min⁻¹.','Divide by 1000 to convert mL to L.','21 L min⁻¹.'],21),
short('Explain how blood redistribution and oxygen extraction support the working muscles.',4,['Working muscle arterioles dilate, increasing local flow.','Some less active beds can constrict, redistributing available flow.','Muscle extraction increases arterio-venous oxygen difference.','Greater flow and extraction support increased oxygen consumption/aerobic ATP resynthesis.']),
essay('Analyse how the rower’s cardiovascular and respiratory responses work together to support sustained exercise.',8,['Heart rate/stroke volume and cardiac output.','Ventilation, alveolar gradients, haemoglobin carriage and muscle unloading.','Venous return and extraction; links between mechanisms rather than unrelated lists.','Training status/intensity and limits of interpreting a single test stage.']),
essay('Evaluate the claim that successful rowing performance depends only on aerobic energy supply. Use the case and draw on anatomy, energy systems and neuromuscular function.',15,['Aerobic capacity is important for sustained work, with delivery and extraction adaptations.','ATP–PC and glycolytic supply contribute during starts, changes of pace and the finishing effort.','All systems overlap; contribution depends on intensity/duration rather than an abrupt on/off switch.','Fibre recruitment, force, technique and recovery also affect performance.','A judgement should explain why aerobic importance does not imply sole dependence.'])]),
section('Section B · Skill acquisition','<p><b>Fictional case:</b> A novice basketball player can pass accurately in an unopposed drill but struggles when defenders and several passing options are introduced. Recorded reaction time is 0.28 s and movement time 0.34 s.</p>',['skill-continua','guidance-feedback','transfer'],[
short('Calculate response time and distinguish it from reaction time.',2,['Response time = 0.28 + 0.34 = 0.62 s.','Reaction time ends at movement initiation; response time also includes movement.'],None),
short('Explain why adding realistic passing alternatives can increase reaction time.',3,['The player must discriminate/select among more possible responses.','Hick’s law predicts longer choice reaction time as alternatives increase.','A novice may need more processing before selecting the pass; anticipation/learning can modify the effect.']),
short('Justify distributed and variable practice for this player.',4,['Distributed practice includes rest/feedback and helps manage novice fatigue/attention.','Explain how this preserves practice quality.','Variable practice changes relevant defender/target conditions.','It develops adaptable responses suited to the open competitive skill.']),
essay('Analyse how guidance and feedback could change as this player progresses towards autonomous performance.',8,['Clear demonstration and manageable cues for cognitive learning.','Specific knowledge of performance as technique becomes more consistent.','Intrinsic feedback and selective external feedback at greater expertise.','Avoid dependence/overload; feedback should respond to evidence rather than a fixed schedule.']),
essay('Evaluate whether repeating the same unopposed passing drill is sufficient preparation for competitive basketball. Apply skill classification, information processing and schema theory.',15,['Repetition can establish basic coordination and confidence.','Competition is open and requires selective attention, perception and response selection.','Variable conditions support adaptable recall/recognition schemas.','Representative pressure and feedback support transfer, while excessive complexity can overload a novice.','A staged whole/part or progressive practice approach should be justified with the learner’s needs.'])]),
section('Section C · Sport and society','<p><b>Fictional case:</b> A local football project offers discounted sessions but has no accessible transport and little provision at times suitable for carers. A sponsor offers funding in exchange for prominent coverage of the elite team rather than the community sessions.</p>',['popular-recreation','amateur-professional','inequality'],[
short('Distinguish prejudice from discrimination.',2,['Prejudice is a pre-judged attitude or belief.','Discrimination is unequal treatment/action; an applied example may show the distinction.']),
short('Explain how improved transport helped the development of organised sport during industrialisation.',3,['Travel between towns became more practical.','Regular inter-club fixtures became possible.','Wider competition encouraged common rules and governing structures.']),
short('Explain two reasons why discounted sessions alone may not remove participation barriers in the case.',4,['Transport/accessibility remains a barrier.','A reduced fee does not make an inaccessible journey possible.','Timing/caring responsibilities remain a barrier.','A session can be affordable yet impractical to attend regularly.']),
essay('Analyse the interrelationship between media, sponsorship and sport using the proposed funding agreement.',8,['Coverage attracts audience and commercial interest.','Funding can improve provision and support elite opportunities.','Sponsor/media preferences may direct resources towards marketable events.','Consider effects on grassroots access and stakeholder priorities, rather than treating revenue as an automatic universal benefit.']),
essay('Evaluate how social institutions and commercial change have shaped access to football from industrialisation to the present. Connect historical development with the fictional project.',15,['Factories, churches, schools, authorities and transport contributed to organised provision.','Codification and governing bodies supported regular competition.','Class, gender, disability and economic inequalities affect opportunity.','Post-war media/commercialisation expanded resources and visibility but distributed them unevenly.','A developed judgement should identify matched participation solutions and avoid portraying access as automatically equal today.'])])]))
papers.append(dict(id='pe-paper-2',paper=2,title='Paper 2 · Optimising sporting performance',marks=105,minutes=120,coverage=['Exercise physiology and biomechanics','Sport psychology','Sport, society and technology'],questions=[
section('Section A · Exercise physiology and biomechanics','<p><b>Fictional case:</b> An 80 kg sprinter experiences a triangular horizontal resultant-force pulse of peak 1200 N lasting 0.20 s. Their coach plans a training block and taper. All values are simplified educational data.</p>',['levers','angular-motion','projectile-motion'],[
short('Calculate the impulse from the horizontal force pulse.',2,['½ × 1200 × 0.20.','120 N s.'],120),
short('Calculate the resulting change in horizontal velocity, showing the relationship used.',3,['Impulse = change in momentum = mass × velocity change.','Velocity change = 120/80.','1.5 m s⁻¹ in the force direction.'],1.5),
short('Explain how specificity and recovery should influence the sprinter’s training design.',4,['Include appropriate high-intensity actions matched to sprint force/speed demands.','Explain how these target the required adaptations.','Provide suitable recovery between quality efforts and sessions.','Recovery supports restored capacity/adaptation and limits loss of quality from accumulated fatigue.']),
essay('Analyse why the sprinter’s coach should use more than peak force when interpreting the test and planning training.',8,['Impulse depends on force–time area, including duration and shape.','Mass influences the velocity change produced by a given impulse.','Direction and whether force is resultant matter.','Standardisation, repeated tests and relevance to competitive technique support interpretation.']),
essay('Evaluate a plan that increases training intensity and volume every day until a championship. Apply training principles, periodisation, recovery and biomechanics.',15,['Progressive overload requires managed demand, not unlimited daily increases.','Specificity and high-quality force application matter for sprinting.','Fatigue can alter coordination and reduce effective impulse or movement quality.','Recovery, sleep and suitable nutrition support adaptation; injury risks require management.','A taper can reduce volume while retaining suitable intensity; timing should respond to evidence and individual needs.'])]),
section('Section B · Sport psychology','<p><b>Fictional case:</b> An experienced penalty taker becomes worried before a final, reports tense shoulders and misses. Their coach concludes that the miss proves a weak personality. Several teammates also argue and stop supporting one another.</p>',['arousal','anxiety','goal-setting'],[
short('Distinguish cognitive and somatic anxiety using the case.',2,['Worry about the final/missing is cognitive anxiety.','Bodily tension such as tense shoulders is somatic anxiety.']),
short('Explain an interactionist challenge to the coach’s personality conclusion.',3,['Behaviour reflects personal and environmental factors.','The final adds pressure/evaluation and may change the athlete’s state.','One missed penalty does not establish a fixed weak trait or prove its cause.']),
short('Justify one cognitive and one somatic stress-management technique for the athlete.',4,['Use a practised task cue, imagery or credible positive self-talk.','Explain how it redirects worry towards controllable execution.','Use practised breathing, centering or relaxation.','Explain the link to bodily tension and the need to practise/evaluate the routine.']),
essay('Analyse how feedback and attribution after the miss could affect the athlete’s motivation and self-efficacy.',8,['Stable uncontrollable inability explanations can reduce expectations/persistence.','Evidence-based controllable technique/preparation explanations can support change.','Mastery progress, credible persuasion and relevant modelling can support efficacy.','Avoid false reassurance or blaming every failure on the athlete; consider alternative causes.']),
essay('Evaluate how leadership, cohesion and arousal management could help the whole team prepare for another final.',15,['Distinguish task/social cohesion and coordination/motivational losses.','Use roles, shared goals and representative practice to target actual group processes.','Leadership should fit required/preferred behaviour and the sporting situation.','Arousal theory supports individualised preparation rather than one universal optimum.','Connect individual confidence and group functioning, considering limitations and measures of improvement.'])]),
section('Section C · Sport, society and technology','<p><b>Fictional case:</b> A club buys a tracking system. A supplier claims the data prove which players will become elite. Devices differ between age groups. Sponsorship pays for the system but the junior programme loses funding. A player is pressured to use a prohibited substance to keep a contract.</p>',['ethics','doping','activity-concepts'],[
short('Distinguish validity and reliability in evaluating the tracking measurements.',2,['Validity concerns whether the measure assesses the intended quality.','Reliability concerns consistency under comparable conditions.']),
short('Explain one role of each: a national governing body, UK Sport and an institute of sport.',3,['A governing body provides sport-specific organisation/pathways.','UK Sport supports the high-performance Olympic/Paralympic system.','An institute provides specialist services such as sports science, medicine or performance support.']),
short('Explain two problems with comparing the age groups’ tracking data directly.',4,['Different device sampling/processing can cause systematic measurement differences.','This can mimic a performance difference.','Age/maturation, role or session demands can differ.','Distance/tracking alone cannot isolate talent or predict every future elite performer.']),
essay('Analyse how data integrity and contextual interpretation could improve the club’s use of sports analytics.',8,['Standardise/calibrate suitable equipment and document processing.','Use accurate labelling, consistent conditions and appropriate access/security.','Consider uncertainty, missing data and multiple measures.','Interpret with role, maturation and opportunity; correlation/prediction is not proof of a single cause.']),
essay('Evaluate whether commercial and technological development necessarily improves sport. Use the case, considering participation, elite performance, ethics and performer welfare.',15,['Funding and technology can improve coaching, analysis, facilities and opportunity.','Unequal allocation may reduce grassroots provision or inclusion.','Overclaiming data can distort selection and reinforce unequal opportunities.','Contract/reward pressures may interact with doping and welfare harms; banned enhancement is not justified by commercial gain.','Balance stakeholders and conditions, concluding how governance and evidence can influence whether benefits are realised.'])])]))
(R/'paper-bank.json').write_text(json.dumps(papers,ensure_ascii=False,indent=2),encoding='utf-8')
(R/'pe-data.js').write_text('window.PE_COURSE='+json.dumps(C,ensure_ascii=False).replace('</','<\\/')+';\nwindow.PE_PAPERS='+json.dumps(papers,ensure_ascii=False).replace('</','<\\/')+';\n',encoding='utf-8')
print('Built',len(papers),'papers:',[sum(a['m']for q in p['questions']for a in q['parts'])for p in papers])
